from research_helpers import *
C=ev('https://clene.com/pipeline/','Current company pipeline names four separate nanotherapeutics. Study names are not separate products; no marketing approval asserted.')
S=ev('https://clene.com/pipeline/','Company biography identifies proprietary Clean-Surface Nanocrystal therapeutic manufacturing platform.')
ps=[p('CNM-Au8','Investigational gold nanocrystal suspension for ALS, multiple sclerosis and Parkinson disease.',C,'development'),p('CNM-ZnAg','Investigational zinc-silver ionic solution with antimicrobial and antiviral research applications.',C,'development'),p('CNM-AgZn17','Investigational topical silver/zinc ion polymer gel for infection and wound healing.',C,'development'),p('CNM-PtAu7','Research-stage gold-platinum nanotherapeutic studied in tumor cell lines.',C,'research'),p('Clene Clean-Surface Nanocrystal platform','Proprietary manufacturing technology for clean-surfaced nanotherapeutics.',S,'development',typ='technology',aliases=['CSN'])]
cs=[company('Clene Inc.',ps,[C,S],'Four named current pipeline programmes and manufacturing platform reviewed. No trial-name duplicates or approval claims. Supplements, historic programmes and latest indication-level trial stages remain to verify.')]
T=ev('https://radiuspharm.com/tymlos/','Current company product page links prescribing information for abaloparatide injection.')
A=ev('https://radiuspharm.com/partnerships/','Company identifies TYMLOS and ELADYNOS regional brands and OSTABALO abaloparatide acetate Japan brand; regional formulation details require separate review.')
B=ev('https://radiuspharm.com/radius-health-announces-expansion-of-its-bone-health-business-through-the-exclusive-licensing-of-u-s-rights-to-binosto-for-osteoporosis/','September 2023 issuer announcement establishes US exclusive license from EffRx; current product page still listed.')
E=ev('https://radiuspharm.com/radius-announces-royalty-purchase-agreement-with-dri-healthcare-to-sell-a-portion-of-its-royalty-and-commercial-milestone-interest-in-elacestrant-for-up-to-140-million/','August 2023 issuer confirms Radius development, Menarini commercialization license in 2020, FDA approval January 2023 and sale of part of royalty stream.')
H=ev('https://www.sec.gov/Archives/edgar/data/1428522/000162828021003172/rdus-20201231.htm','2020 annual report identifies transdermal abaloparatide, RAD011 acquisition and RAD140 sale to Ellipses. Historic evidence does not establish current active development.')
r=[p('TYMLOS','Abaloparatide injection for osteoporosis.',T,'commercial',typ='product',aliases=['ELADYNOS'],evidence=[T,A]),p('BINOSTO','Alendronate sodium effervescent tablet for oral solution in osteoporosis.',B,'commercial',roles=['licensee'],typ='product',territory='US'),p('ORSERDU','Elacestrant estrogen receptor degrader; historically developed by Radius and commercialized by Menarini/Stemline.',E,'commercial',aliases=['RAD1901'],typ='product',attributes={'company_relationship_scope':'historical developer; commercialization licensed to Menarini in 2020; partial royalty interest sold in 2023'}),p('Abaloparatide transdermal system','Historical investigational transdermal abaloparatide formulation, distinct from approved injection.',H,attributes={'current_program_status':'unverified; historical 2020 programme'}),p('RAD011','Historical investigational synthetic cannabidiol oral solution programme.',H,attributes={'current_program_status':'unverified; historical acquired asset; not approved product'}),p('RAD140','Historical selective androgen receptor modulator programme sold to Ellipses in 2020.',H,attributes={'company_relationship_scope':'historical developer; asset sold to Ellipses in 2020'})]
cs.append(company('Radius Heal',r,[T,A,B,E,H],'Current two marketed medicines and selected historical programmes reviewed. ELADYNOS grouped with TYMLOS; Japanese OSTABALO formulation and historic programme outcomes require further review. March 2026 Paratek combination requires group-scope review; no automatic attribution of all combined-company products.'))
(out/'batch-0080.json').write_text(json.dumps({'companies':cs},indent=2));print(sum(len(c['products']) for c in cs))
